<script setup>import {ref,onMounted} from 'vue';import {api,money,toast,time,labels} from '../core';import State from '../components/State.vue';const orders=ref([]),loading=ref(false),error=ref(''),busy=ref('');async function load(){loading.value=true;error.value='';try{orders.value=await api('/orders')}catch(e){error.value=e.message}finally{loading.value=false}}async function action(o,action,success=true){busy.value=o.id;try{await api('/orders/'+o.id+'/'+action,'POST',action==='pay'?{success}:undefined);toast(action==='pay'&&!success?'模拟支付失败，订单仍待付款':'操作已保存');await load()}catch(e){toast(e.message,true)}finally{busy.value=''}}onMounted(load);</script><template><section class="shell section"><p class="eyebrow">EVERY LITTLE ORDER OF LOVE</p><h1>我的订单</h1><State :loading="loading" :error="error" :empty="!orders.length" text="还没有订单，去商城挑选好物吧" @retry="load"/><article v-for="o in orders" :key="o.id" class="panel order-panel"><div class="row between wrap"><div><span class="eyebrow">{{o.id.slice(0,8).toUpperCase()}}</span><p class="hint">{{time(o.createdAt)}}</p></div><span class="badge">{{o.status==='PENDING'?'待付款':labels[o.status]}}</span></div><div v-for="i in o.items" :key="i.productId" class="order-product"><img :src="i.image" :alt="i.name"><div><h3>{{i.name}}</h3><p class="muted">¥{{money(i.price)}} × {{i.quantity}}</p></div><strong>¥{{money(i.price*i.quantity)}}</strong></div><div class="order-foot"><div><p>{{o.recipient}} · {{o.phone}}</p><p class="muted">{{o.address}}</p><p v-if="o.carrier">{{o.carrier}} · {{o.tracking}}</p><p class="hint">满减 −¥{{money(o.discount)}} · 八折优惠 −¥{{money(o.subsidy)}}</p></div><div class="order-buttons"><strong>实付 / 应付 <span class="price">¥{{money(o.payable)}}</span></strong><div class="row wrap" v-if="o.status==='PENDING'"><button class="btn small" :disabled="!!busy" @click="action(o,'pay')">模拟付款成功</button><button class="btn secondary small" :disabled="!!busy" @click="action(o,'pay',false)">模拟失败</button><button class="text-button" :disabled="!!busy" @click="action(o,'cancel')">取消订单</button></div><button v-if="o.status==='SHIPPED'" class="btn small" :disabled="!!busy" @click="action(o,'receive')">确认收货</button></div></div></article></section></template>
